package local.skyfamily;
import android.graphics.Typeface;import android.os.Handler;import android.text.*;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
final class CalendarPane extends FrameLayout {
 final CalendarPhotosActivity host;final Map<String,String> drafts;final Handler timer=new Handler();final java.text.SimpleDateFormat keys=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);final Calendar month=Calendar.getInstance();final LinearLayout layout,monthColumn,board;final ScrollView monthScroll,entryScroll;final TextView monthTitle,selectedLabel,status;final EditText editor;String selected;boolean loading=false,dirty=false;int orientation=-1;
 CalendarPane(CalendarPhotosActivity activity,Map<String,String> pending){super(activity);host=activity;drafts=pending;keys.setLenient(false);String saved=host.get("calendar.selected");try{if(!saved.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"))throw new Exception();month.setTime(keys.parse(saved));}catch(Exception error){month.setTime(new Date());}month.set(Calendar.HOUR_OF_DAY,12);selected=keys.format(month.getTime());month.set(Calendar.DAY_OF_MONTH,1);layout=new LinearLayout(host);addView(layout,new FrameLayout.LayoutParams(-1,-1));monthColumn=new LinearLayout(host);monthColumn.setOrientation(1);monthColumn.setPadding(host.dp(5),host.dp(5),host.dp(5),host.dp(5));monthColumn.setBackground(host.controlBackground());LinearLayout navigation=new LinearLayout(host);navigation.setGravity(Gravity.CENTER_VERTICAL);monthColumn.addView(navigation,new LinearLayout.LayoutParams(-1,host.dp(54)));action(navigation,"<",48,()->shift(-1));monthTitle=host.paperText("",22,PaperActivity.INK);monthTitle.setGravity(Gravity.CENTER);monthTitle.setSingleLine(true);monthTitle.setEllipsize(TextUtils.TruncateAt.END);navigation.addView(monthTitle,new LinearLayout.LayoutParams(0,-1,1));action(navigation,">",48,()->shift(1));monthScroll=new ScrollView(host);monthScroll.setFillViewport(true);monthColumn.addView(monthScroll,new LinearLayout.LayoutParams(-1,0,1));board=new LinearLayout(host);board.setOrientation(1);monthScroll.addView(board,new ScrollView.LayoutParams(-1,host.dp(324)));monthScroll.addOnLayoutChangeListener((view,l,t,r,b,ol,ot,or,ob)->sizeBoard());entryScroll=new ScrollView(host);entryScroll.setFillViewport(true);LinearLayout entry=new LinearLayout(host);entry.setOrientation(1);entry.setPadding(host.dp(14),host.dp(10),host.dp(14),host.dp(14));entry.setBackground(host.controlBackground());entryScroll.addView(entry,new ScrollView.LayoutParams(-1,-2));selectedLabel=host.paperText("",20,PaperActivity.INK);entry.addView(selectedLabel);TextView hint=host.paperText("Local day entry / changes save on this device",14,PaperActivity.MUTE);entry.addView(hint);editor=new EditText(host);editor.setTextColor(PaperActivity.INK);editor.setHintTextColor(PaperActivity.MUTE);editor.setHint("Add plans for this day");editor.setGravity(Gravity.TOP);editor.setMinLines(6);editor.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);entry.addView(editor,new LinearLayout.LayoutParams(-1,-2));status=host.paperText("",14,PaperActivity.MUTE);entry.addView(status);LinearLayout actions=new LinearLayout(host);entry.addView(actions,new LinearLayout.LayoutParams(-1,host.dp(52)));action(actions,"Save",0,()->{dirty=true;flush();});action(actions,"Today",0,()->select(System.currentTimeMillis()));layout.addView(monthColumn);layout.addView(entryScroll);load();editor.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence text,int a,int c,int f){}public void onTextChanged(CharSequence text,int a,int b,int c){if(loading)return;dirty=true;drafts.put(selected,text.toString());status.setText("Saving...");timer.removeCallbacksAndMessages(null);timer.postDelayed(()->flush(),700);}public void afterTextChanged(Editable text){}});render();}
 void action(LinearLayout row,String title,int width,Runnable action){TextView button=host.paperText(title,18,PaperActivity.INK);button.setGravity(Gravity.CENTER);button.setBackground(host.controlBackground());button.setFocusable(true);row.addView(button,new LinearLayout.LayoutParams(width==0?0:host.dp(width),-1,width==0?1:0));button.setOnClickListener(view->action.run());}
 void load(){loading=true;editor.setText(drafts.containsKey(selected)?drafts.get(selected):host.get("event."+selected));loading=false;dirty=drafts.containsKey(selected);selectedLabel.setText(selected);status.setText(dirty?"Unsaved draft / tap Save":"Stored locally");}
 boolean flush(){timer.removeCallbacksAndMessages(null);if(!dirty)return true;String value=editor.getText().toString();drafts.put(selected,value);if(host.prefs.edit().putString("event."+selected,value).commit()){drafts.remove(selected);dirty=false;status.setText("Saved on this device");render();return true;}status.setText("NOT SAVED / keep app open and check storage");return false;}
 void shift(int direction){if(!flush())return;month.add(Calendar.MONTH,direction);render();}
 void select(long milliseconds){if(!flush())return;Calendar date=Calendar.getInstance();date.setTimeInMillis(milliseconds);date.set(Calendar.HOUR_OF_DAY,12);selected=keys.format(date.getTime());month.setTime(date.getTime());month.set(Calendar.DAY_OF_MONTH,1);host.prefs.edit().putString("calendar.selected",selected).apply();load();render();}
 protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);boolean side=w>=host.dp(660)||(w>=host.dp(480)&&w>h*1.35f);int next=side?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL;if(next!=orientation){orientation=next;layout.setOrientation(next);LinearLayout.LayoutParams first=new LinearLayout.LayoutParams(side?0:-1,side?-1:0,side?1.8f:1.9f),second=new LinearLayout.LayoutParams(side?0:-1,side?-1:0,side?1:1);first.setMargins(0,0,side?host.dp(10):0,side?0:host.dp(10));monthColumn.setLayoutParams(first);entryScroll.setLayoutParams(second);}post(()->sizeBoard());}
 void sizeBoard(){int minimum=host.dp(36+6*48);float font=Math.max(1,host.getResources().getConfiguration().fontScale);int target=Math.max(monthScroll.getHeight(),Math.round(minimum*font));ViewGroup.LayoutParams size=board.getLayoutParams();if(size.height!=target){size.height=target;board.setLayoutParams(size);}}
 void render(){board.removeAllViews();monthTitle.setText(new java.text.SimpleDateFormat("MMMM yyyy",Locale.getDefault()).format(month.getTime()));int firstDay=month.getFirstDayOfWeek();String[] weekdays=new DateFormatSymbols(Locale.getDefault()).getShortWeekdays();LinearLayout heading=new LinearLayout(host);board.addView(heading,new LinearLayout.LayoutParams(-1,host.dp(36)));for(int column=0;column<7;column++){int day=(firstDay-1+column)%7+1;TextView name=host.paperText(weekdays[day],14,PaperActivity.MUTE);name.setGravity(Gravity.CENTER);name.setSingleLine(true);heading.addView(name,new LinearLayout.LayoutParams(0,-1,1));}Calendar cursor=(Calendar)month.clone();int offset=(cursor.get(Calendar.DAY_OF_WEEK)-firstDay+7)%7;cursor.add(Calendar.DAY_OF_MONTH,-offset);String today=keys.format(new Date());for(int week=0;week<6;week++){LinearLayout row=new LinearLayout(host);board.addView(row,new LinearLayout.LayoutParams(-1,0,1));for(int column=0;column<7;column++){final long date=cursor.getTimeInMillis();String key=keys.format(cursor.getTime()),entry=drafts.containsKey(key)?drafts.get(key):host.get("event."+key);DayCell cell=new DayCell(cursor.get(Calendar.DAY_OF_MONTH),cursor.get(Calendar.MONTH)==month.get(Calendar.MONTH),key.equals(selected),key.equals(today),entry);cell.setContentDescription(key+(entry.isEmpty()?" / no entry":" / "+entry));cell.setFocusable(true);cell.setOnClickListener(view->select(date));LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(0,-1,1);size.setMargins(host.dp(2),host.dp(2),host.dp(2),host.dp(2));row.addView(cell,size);cursor.add(Calendar.DAY_OF_MONTH,1);}}sizeBoard();}
 class DayCell extends LinearLayout{final TextView number,preview;DayCell(int day,boolean thisMonth,boolean chosen,boolean today,String entry){super(host);setOrientation(1);setGravity(Gravity.CENTER);setPadding(host.dp(2),host.dp(3),host.dp(2),host.dp(3));setBackground(host.shape(chosen?host.palette().rail:host.palette().surface,chosen?PaperActivity.INK:PaperActivity.LINE,10));setSelected(chosen);number=host.paperText(String.valueOf(day),22,thisMonth?PaperActivity.INK:PaperActivity.MUTE);number.setGravity(Gravity.CENTER);number.setTypeface(null,today||chosen?Typeface.BOLD:Typeface.NORMAL);addView(number,new LinearLayout.LayoutParams(-1,-2));View dot=new View(host);dot.setBackgroundColor(entry.isEmpty()?android.graphics.Color.TRANSPARENT:PaperActivity.INK);addView(dot,new LinearLayout.LayoutParams(host.dp(4),host.dp(4)));preview=host.paperText(entry.split("\n",2)[0],14,PaperActivity.MUTE);preview.setSingleLine(true);preview.setEllipsize(TextUtils.TruncateAt.END);preview.setGravity(Gravity.CENTER);addView(preview,new LinearLayout.LayoutParams(-1,-2));preview.setVisibility(GONE);}protected void onSizeChanged(int w,int h,int ow,int oh){super.onSizeChanged(w,h,ow,oh);float density=getResources().getDisplayMetrics().scaledDensity;number.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,Math.max(18*density,Math.min(34*density,Math.min(w*.42f,h*.38f))));preview.setVisibility(h>=host.dp(80)?VISIBLE:GONE);}}
 protected void onDetachedFromWindow(){flush();timer.removeCallbacksAndMessages(null);super.onDetachedFromWindow();}
}
